QUESTION = {
    "type": "choice",
    "instructions": ("Based on this evidence, does the target firm's production depend on what the "
                     "source firm communicates through this channel?"),
    "criteria": {"A": "yes, the target firm's choices depend on this channel",
                 "B": "no, the target firm acts independently of this channel"},
}
NOUL = {"type": "noul", "instructions": "Does the target firm's behaviour depend on this channel?"}

subprocess.run("pip -q install uv && git clone -q https://github.com/jaredpalmer/kev.git /tmp/kev", shell=True, check=True)
subprocess.run("cd /tmp/kev && uv sync --extra serve", shell=True, check=True)

results = {}
for port, model in [(8011, "jaredpalmer/kev-4b"), (8012, "jaredpalmer/kev-0.8b")]:
    log = open(f"/kaggle/working/{model.split('/')[1]}_server.log", "w")
    srv = subprocess.Popen(f"cd /tmp/kev && uv run --extra serve python -m kev.serve --run {model} --port {port} --device cuda",
                           shell=True, stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
    up = False
    for _ in range(240):
        try:
            requests.get(f"http://127.0.0.1:{port}/v1/models", timeout=5); up = True; break
        except Exception:
            time.sleep(5)
    print(model, "server up" if up else "server FAILED")
    if up:
        out = []
        for c in CANDS:
            body = {"state": {"evidence": c["evidence"]}, "model": "kev-latest",
                    "questions": {"dep": QUESTION, "dep_noul": NOUL}}
            r = requests.post(f"http://127.0.0.1:{port}/v1/systemone", json=body, timeout=600).json()
            out.append({"game": c["game"], "id": c["id"], "verified": c["verified"],
                        "p_choice": r["answers"]["dep"]["probabilities"]["A"],
                        "p_noul": r["answers"]["dep_noul"]["noul"]})
        results[model] = out
        print(model, "scored", len(out))
    os.killpg(srv.pid, 9); srv.wait(); time.sleep(10)
    json.dump(results, open("/kaggle/working/kev_scores.json", "w"), indent=1)
json.dump(results, open("/kaggle/working/kev_scores.json", "w"), indent=1)
print("done")
